import { useEffect, useRef, useState } from 'react';
import type { CSSProperties, Dispatch, FormEvent, SetStateAction } from 'react';
import { Link, Route, Switch, useLocation, Router as WouterRouter } from 'wouter';
import {
  ArrowDown, ArrowLeft, ArrowRight, ArrowUp, Bell, BookOpen, CalendarDays, Check,
  CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Circle, Clock3, Flame,
  GraduationCap, LayoutDashboard, ListChecks, NotebookPen,
  Pause, Pencil, Play, Plus, RotateCcw, Search, Settings2, Sparkles, Target,
  Trash2, TrendingUp, X, Zap, BarChart3, Layers3, AlarmClock,
} from 'lucide-react';
import NotFound from '@/pages/not-found';

type TopicStatus = 'not_started' | 'in_progress' | 'completed';
type Priority = 'low' | 'normal' | 'high';
type Subject = { id:string; name:string; order:number };
type Lesson = { id:string; subjectId:string; name:string; order:number };
type Topic = { id:string; subjectId:string; lessonId:string; name:string; status:TopicStatus; priority:Priority };
type Note = { id:string; title:string; body:string; subjectId:string|null; lessonId:string|null; updatedAt:string };
type Flashcard = { id:string; question:string; answer:string; subjectId:string|null; lessonId:string|null };
type Question = { prompt:string; options:[string,string,string,string]; correctIndex:number };
type Attempt = { score:number; total:number; completedAt:string };
type Quiz = { id:string; title:string; subjectId:string|null; lessonId:string|null; questions:Question[]; attempts:Attempt[] };
type TimetableEntry = { id:string; weekday:number; startTime:string; endTime:string; subjectId:string; lessonId:string|null };
type Exam = { id:string; name:string; subjectId:string; date:string };
type TaskType = 'homework'|'assignment'|'revision'|'other';
type Task = { id:string; title:string; type:TaskType; dueDate:string; subjectId:string|null; lessonId:string|null; completed:boolean };
type StudySession = { id:string; startedAt:string; durationSeconds:number; subjectId:string|null };
type Reminder = { id:string; title:string; type:'study'|'exam'|'assignment'|'revision'; dueAt:string; subjectId:string|null; completed:boolean };
type Store = { subjects:Subject[]; lessons:Lesson[]; topics:Topic[]; notes:Note[]; flashcards:Flashcard[]; quizzes:Quiz[]; timetable:TimetableEntry[]; exams:Exam[]; tasks:Task[]; sessions:StudySession[]; reminders:Reminder[]; preferences:{displayName:string; focusMinutes:number; breakMinutes:number} };
const STORAGE_KEY = 'studymate-data-v1';
const EMPTY:Store = { subjects:[], lessons:[], topics:[], notes:[], flashcards:[], quizzes:[], timetable:[], exams:[], tasks:[], sessions:[], reminders:[], preferences:{displayName:'',focusMinutes:25,breakMinutes:5} };
const days = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const shortDays = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const uid = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`;
const localDate = (d=new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const localDateTime = (d=new Date()) => `${localDate(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
const dayIndex = (d=new Date()) => (d.getDay()+6)%7;
const prettyDate = (d=new Date()) => d.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});
const loadStore = ():Store => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return EMPTY;
    const parsed = JSON.parse(raw);
    return { ...EMPTY, ...parsed, preferences:{...EMPTY.preferences,...parsed.preferences},
      subjects:Array.isArray(parsed.subjects)?parsed.subjects:[], lessons:Array.isArray(parsed.lessons)?parsed.lessons:[],
      topics:Array.isArray(parsed.topics)?parsed.topics:[], notes:Array.isArray(parsed.notes)?parsed.notes:[],
      flashcards:Array.isArray(parsed.flashcards)?parsed.flashcards:[], quizzes:Array.isArray(parsed.quizzes)?parsed.quizzes:[],
      timetable:Array.isArray(parsed.timetable)?parsed.timetable:[], exams:Array.isArray(parsed.exams)?parsed.exams:[],
      tasks:Array.isArray(parsed.tasks)?parsed.tasks:[], sessions:Array.isArray(parsed.sessions)?parsed.sessions:[],
      reminders:Array.isArray(parsed.reminders)?parsed.reminders:[] };
  } catch { return EMPTY; }
};
const pct = (done:number,total:number) => total ? Math.round(done/total*100) : 0;
const mins = (s:number) => Math.floor(s/60);
const idTest = (str:string) => str.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');

type Field = { key:string; label:string; kind?:'text'|'date'|'time'|'datetime-local'|'number'|'textarea'|'select'; options?:{value:string;label:string;subjectId?:string}[]; required?:boolean; placeholder?:string };
type ModalConfig = { title:string; fields:Field[]; initial?:Record<string,any>; submitLabel?:string; onSave:(values:Record<string,any>)=>void };

function App(){
  const [store,setStore] = useState<Store>(loadStore);
  const [modal,setModal] = useState<ModalConfig|null>(null);
  const [toast,setToast] = useState('');
  const [location] = useLocation();
  useEffect(()=>{ try{localStorage.setItem(STORAGE_KEY,JSON.stringify(store));}catch{} },[store]);
  useEffect(()=>{ if(!toast)return; const t=setTimeout(()=>setToast(''),2600); return ()=>clearTimeout(t);},[toast]);
  useEffect(()=>{
    if(!('Notification'in window)||Notification.permission!=='granted')return;
    const timers=store.reminders.filter(r=>!r.completed&&new Date(r.dueAt).getTime()>Date.now()).map(r=>window.setTimeout(()=>new Notification('StudyMate reminder',{body:r.title}),new Date(r.dueAt).getTime()-Date.now()));
    return ()=>timers.forEach(window.clearTimeout);
  },[store.reminders]);
  const notify=(s:string)=>setToast(s);
  const save=(type:keyof Store, value:any, id?:string)=>{
    setStore(prev=>{
      const list=(prev[type] as any[]);
      if(!Array.isArray(list))return prev;
      return {...prev,[type]:id?list.map(item=>item.id===id?{...item,...value}:item):[...list,{id:uid(),...value}]};
    });
    notify(id?'Changes saved':'Added to your space');
  };
  const remove=(type:keyof Store,id:string)=>{
    setStore(prev=>{
      const next={...prev,[type]:(prev[type] as any[]).filter((x:any)=>x.id!==id)} as Store;
      if(type==='subjects'){
        const lessonIds=prev.lessons.filter(x=>x.subjectId===id).map(x=>x.id);
        next.lessons=prev.lessons.filter(x=>x.subjectId!==id);
        next.topics=prev.topics.filter(x=>x.subjectId!==id);
        next.notes=prev.notes.filter(x=>x.subjectId!==id);
        next.flashcards=prev.flashcards.filter(x=>x.subjectId!==id);
        next.quizzes=prev.quizzes.filter(x=>x.subjectId!==id);
        next.timetable=prev.timetable.filter(x=>x.subjectId!==id);
        next.exams=prev.exams.filter(x=>x.subjectId!==id);
        next.tasks=prev.tasks.filter(x=>x.subjectId!==id);
        next.sessions=prev.sessions.filter(x=>x.subjectId!==id);
        next.reminders=prev.reminders.filter(x=>x.subjectId!==id);
        void lessonIds;
      }
      if(type==='lessons'){
        next.topics=prev.topics.filter(x=>x.lessonId!==id);
        next.notes=prev.notes.map(x=>x.lessonId===id?{...x,lessonId:null}:x);
        next.flashcards=prev.flashcards.map(x=>x.lessonId===id?{...x,lessonId:null}:x);
        next.quizzes=prev.quizzes.map(x=>x.lessonId===id?{...x,lessonId:null}:x);
        next.timetable=prev.timetable.map(x=>x.lessonId===id?{...x,lessonId:null}:x);
        next.tasks=prev.tasks.map(x=>x.lessonId===id?{...x,lessonId:null}:x);
      }
      return next;
    });
    notify('Removed');
  };
  const reorder=(type:'subjects'|'lessons',id:string,dir:number)=>{
    setStore(prev=>{const items=[...prev[type]].sort((a,b)=>a.order-b.order);const i=items.findIndex(x=>x.id===id),j=i+dir;if(j<0||j>=items.length)return prev;[items[i],items[j]]=[items[j],items[i]];return {...prev,[type]:items.map((x,n)=>({...x,order:n}))};});
  };
  const reorderTopic=(id:string,dir:number)=>{
    setStore(prev=>{const current=prev.topics.find(x=>x.id===id);if(!current)return prev;const indices=prev.topics.map((x,i)=>x.lessonId===current.lessonId?i:-1).filter(i=>i>=0);const groupIndex=indices.indexOf(prev.topics.findIndex(x=>x.id===id)),target=groupIndex+dir;if(target<0||target>=indices.length)return prev;const topics=[...prev.topics];[topics[indices[groupIndex]],topics[indices[target]]]=[topics[indices[target]],topics[indices[groupIndex]]];return {...prev,topics};});
    notify('Topic order updated');
  };
  const openForm=(config:ModalConfig)=>setModal(config);
  const addSubject=()=>openForm({title:'Add a subject',fields:[{key:'name',label:'Subject name',required:true,placeholder:'What are you studying?'}],onSave:v=>save('subjects',{name:v.name.trim(),order:store.subjects.length})});
  const editSubject=(s:Subject)=>openForm({title:'Edit subject',initial:{name:s.name},fields:[{key:'name',label:'Subject name',required:true}],onSave:v=>save('subjects',{name:v.name.trim()},s.id)});
  const addLesson=(s:Subject)=>openForm({title:`Add lesson · ${s.name}`,fields:[{key:'name',label:'Lesson name',required:true,placeholder:'e.g. a chapter or unit'}],onSave:v=>save('lessons',{name:v.name.trim(),subjectId:s.id,order:store.lessons.filter(l=>l.subjectId===s.id).length})});
  const editLesson=(l:Lesson)=>openForm({title:'Edit lesson',initial:{name:l.name},fields:[{key:'name',label:'Lesson name',required:true}],onSave:v=>save('lessons',{name:v.name.trim()},l.id)});
  const addTopic=(s:Subject,l:Lesson)=>openForm({title:`Add topic · ${l.name}`,fields:[{key:'name',label:'Topic name',required:true},{key:'priority',label:'Priority',kind:'select',options:[{value:'low',label:'Low'},{value:'normal',label:'Normal'},{value:'high',label:'High'}]}],initial:{priority:'normal'},onSave:v=>save('topics',{name:v.name.trim(),priority:v.priority,status:'not_started',subjectId:s.id,lessonId:l.id})});
  const editTopic=(t:Topic)=>openForm({title:'Edit topic',initial:{name:t.name,priority:t.priority},fields:[{key:'name',label:'Topic name',required:true},{key:'priority',label:'Priority',kind:'select',options:[{value:'low',label:'Low'},{value:'normal',label:'Normal'},{value:'high',label:'High'}]}],onSave:v=>save('topics',{name:v.name.trim(),priority:v.priority},t.id)});
  const selectSubject=store.subjects.map(s=>({value:s.id,label:s.name}));
  const formSubject=(allowNone=true):Field=>({key:'subjectId',label:'Subject',kind:'select',options:[...(allowNone?[{value:'',label:'No subject'}]:[]),...selectSubject]});
  const lessonOptions=(sid:string)=>store.lessons.filter(l=>l.subjectId===sid).map(l=>({value:l.id,label:l.name}));
  const askDelete=(type:keyof Store,id:string,label:string)=>{if(window.confirm(`Remove “${label}”? This cannot be undone.`))remove(type,id);};
  const shellData={store,setStore,notify,save,remove,reorder,reorderTopic,openForm,addSubject,editSubject,addLesson,editLesson,addTopic,editTopic,askDelete,formSubject,lessonOptions};
  return <div className="app-root">
    <aside className="rail">
      <Link href="/" className="brand" data-testid="link-brand"><span className="brand-mark"><GraduationCap size={21}/></span><span>study<span className="brand-light">mate</span></span></Link>
      <div className="rail-label">YOUR SPACE</div>
      <NavLinks current={location}/>
      <div className="rail-bottom">
        <div className="local-status"><span className="status-dot"/><div><strong>Saved on this device</strong><small>Your space stays yours</small></div></div>
        <button className="profile-chip" onClick={()=>openForm({title:'Your study space',initial:{displayName:store.preferences.displayName,focusMinutes:store.preferences.focusMinutes,breakMinutes:store.preferences.breakMinutes},fields:[{key:'displayName',label:'What should we call you?',placeholder:'Your name'},{key:'focusMinutes',label:'Focus minutes',kind:'number'},{key:'breakMinutes',label:'Break minutes',kind:'number'}],onSave:v=>{setStore(p=>({...p,preferences:{displayName:v.displayName||'',focusMinutes:Math.max(1,Number(v.focusMinutes)||25),breakMinutes:Math.max(1,Number(v.breakMinutes)||5)}}));notify('Preferences updated');}})} data-testid="button-preferences"><span className="avatar">{store.preferences.displayName?.[0]?.toUpperCase()||'S'}</span><span><strong>{store.preferences.displayName||'My study space'}</strong><small>Personal workspace</small></span><Settings2 size={16}/></button>
      </div>
    </aside>
    <main className="main-area">
      <header className="topbar"><div className="mobile-brand"><span className="brand-mark"><GraduationCap size={19}/></span>studymate</div><div className="topbar-right"><span className="date-chip"><CalendarDays size={15}/>{prettyDate()}</span><button className="icon-button" aria-label="Set preferences" onClick={()=>openForm({title:'Your study space',initial:{displayName:store.preferences.displayName,focusMinutes:store.preferences.focusMinutes,breakMinutes:store.preferences.breakMinutes},fields:[{key:'displayName',label:'What should we call you?',placeholder:'Your name'},{key:'focusMinutes',label:'Focus minutes',kind:'number'},{key:'breakMinutes',label:'Break minutes',kind:'number'}],onSave:v=>{setStore(p=>({...p,preferences:{displayName:v.displayName||'',focusMinutes:Math.max(1,Number(v.focusMinutes)||25),breakMinutes:Math.max(1,Number(v.breakMinutes)||5)}}));notify('Preferences updated');}})} data-testid="button-settings"><Settings2 size={17}/></button></div></header>
      <div className="page-wrap"><Switch>
        <Route path="/" component={()=> <HomePage {...shellData}/>}/>
        <Route path="/study" component={()=> <StudyPage {...shellData}/>}/>
        <Route path="/notes" component={()=> <NotesPage {...shellData}/>}/>
        <Route path="/planner" component={()=> <PlannerPage {...shellData}/>}/>
        <Route path="/progress" component={()=> <ProgressPage {...shellData}/>}/>
        <Route component={NotFound}/>
      </Switch></div>
      <BottomNav current={location}/>
    </main>
    {modal&&<FormModal config={modal} onClose={()=>setModal(null)} onSubmit={v=>{modal.onSave(v);setModal(null);}}/>}
    {toast&&<div className="toast" role="status" data-testid="status-feedback"><CheckCircle2 size={17}/>{toast}</div>}
  </div>;
}
function NavLinks({current}:{current:string}){
  const links=[['/','Home',LayoutDashboard],['/study','Study',BookOpen],['/notes','Notes',NotebookPen],['/planner','Planner',CalendarDays],['/progress','Progress',BarChart3]] as const;
  return <nav className="rail-nav">{links.map(([href,label,Icon])=><Link href={href} key={href} className={`nav-link ${current===href?'active':''}`} data-testid={`link-nav-${label.toLowerCase()}`}><Icon size={18}/><span>{label}</span>{current===href&&<span className="nav-indicator"/>}</Link>)}</nav>;
}
function BottomNav({current}:{current:string}){
  const links=[['/','Home',LayoutDashboard],['/study','Study',BookOpen],['/notes','Notes',NotebookPen],['/planner','Planner',CalendarDays],['/progress','Progress',BarChart3]] as const;
  return <nav className="bottom-nav">{links.map(([href,label,Icon])=><Link href={href} key={href} className={`bottom-link ${current===href?'active':''}`} data-testid={`mobile-nav-${label.toLowerCase()}`}><Icon size={19}/><span>{label}</span></Link>)}</nav>;
}
type Shared={store:Store;setStore:Dispatch<SetStateAction<Store>>;notify:(s:string)=>void;save:(type:keyof Store,value:any,id?:string)=>void;remove:(type:keyof Store,id:string)=>void;reorder:(type:'subjects'|'lessons',id:string,dir:number)=>void;reorderTopic:(id:string,dir:number)=>void;openForm:(c:ModalConfig)=>void;addSubject:()=>void;editSubject:(s:Subject)=>void;addLesson:(s:Subject)=>void;editLesson:(l:Lesson)=>void;addTopic:(s:Subject,l:Lesson)=>void;editTopic:(t:Topic)=>void;askDelete:(type:keyof Store,id:string,label:string)=>void;formSubject:(allowNone?:boolean)=>Field;lessonOptions:(sid:string)=>{value:string;label:string}[]};
const emptyCopy:Record<string,{title:string;body:string}>={subjects:{title:'Your study space starts here',body:'Add a subject to create a home for lessons, topics, notes, and progress.'},notes:{title:'A fresh page is waiting',body:'Save your own notes as you study. Keep them linked to a subject, or leave them free-standing.'},tasks:{title:'Nothing on your list yet',body:'Add a task when you want a little structure for your next study session.'},exams:{title:'No exams on the horizon',body:'Add an exam and we’ll keep its countdown close by.'},timetable:{title:'Make room for study',body:'Add your regular study times to see the week take shape.'}};
function Empty({kind,onAdd,label='Add',title,body}:{kind:keyof typeof emptyCopy;onAdd:()=>void;label?:string;title?:string;body?:string}){
  const e=emptyCopy[kind];return <div className="empty-state" data-testid={`empty-${kind}`}><div className="empty-orbit"><span className="empty-icon"><BookOpen size={21}/></span><i/><b/></div><h3>{title||e.title}</h3><p>{body||e.body}</p><button className="button button-primary button-small" onClick={onAdd} data-testid={`button-empty-add-${kind}`}><Plus size={15}/>{label}</button></div>;
}
function PageHeading({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:{label:string;onClick:()=>void}}){
  return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action&&<button className="button button-primary" onClick={action.onClick} data-testid={`button-${idTest(action.label)}`}><Plus size={17}/>{action.label}</button>}</div>;
}
function HomePage(p:Shared){
  const {store}=p;const today=localDate();const tasks=store.tasks.filter(t=>!t.completed&&t.dueDate===today);const exams=store.exams.filter(e=>e.date>=today).sort((a,b)=>a.date.localeCompare(b.date));const next=exams[0];const timetable=store.timetable.filter(e=>e.weekday===dayIndex()).sort((a,b)=>a.startTime.localeCompare(b.startTime));
  const seconds=store.sessions.filter(s=>localDate(new Date(s.startedAt))===today).reduce((a,s)=>a+s.durationSeconds,0);
  const total=store.topics.length,done=store.topics.filter(t=>t.status==='completed').length;const streak=calcStreak(store.sessions);
  return <><PageHeading eyebrow="YOUR DAY, YOUR PACE" title={`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}${store.preferences.displayName?`, ${store.preferences.displayName}`:''}.`} description="A little progress, one focused moment at a time." action={{label:'Add a subject',onClick:p.addSubject}}/>
    <section className="welcome-band"><div className="welcome-copy"><span className="mini-kicker"><Sparkles size={14}/>TODAY IS A GOOD DAY TO BEGIN</span><h2>Your next small step<br/><em>is enough.</em></h2><p>Build momentum on your terms. Everything you need is right here.</p><Link className="button button-cream" href="/study" data-testid="link-start-studying">Go to study space <ArrowRight size={16}/></Link></div><div className="orbit-art" aria-hidden="true"><div className="orbit-circle orbit-one"/><div className="orbit-circle orbit-two"/><div className="orbit-book"><BookOpen size={34}/></div><span className="orbit-star star-a">✳</span><span className="orbit-star star-b">+</span><span className="orbit-caption">one thing<br/>at a time</span></div></section>
    <div className="metric-grid">
      <Metric icon={<Clock3/>} label="Study time today" value={seconds?`${Math.floor(seconds/3600)}h ${Math.floor(mins(seconds)%60)}m`:'0 min'} note={seconds?'Look at you showing up.':'Your first session is waiting.'} color="mint"/>
      <Metric icon={<Target/>} label="Syllabus complete" value={`${pct(done,total)}%`} note={`${done} of ${total} topics completed`} color="peach" progress={pct(done,total)}/>
      <Metric icon={<Flame/>} label="Study streak" value={`${streak} ${streak===1?'day':'days'}`} note={streak?'Keep your rhythm going.':'Start a streak with one session.'} color="butter"/>
    </div>
    <div className="home-columns">
      <section className="panel home-panel"><div className="section-title"><div><span className="eyebrow">THE TO-DO LIST</span><h2>Today’s tasks</h2></div><Link href="/planner" className="text-link" data-testid="link-all-tasks">All tasks <ArrowRight size={14}/></Link></div>
        {tasks.length? <div className="compact-list">{tasks.map(t=><TaskRow key={t.id} task={t} {...p}/>)}</div>:<CompactEmpty icon={<ListChecks/>} title="Nothing due today" text="You can add a task whenever you’re ready." action="Plan a task" href="/planner"/>}
      </section>
      <section className="panel home-panel"><div className="section-title"><div><span className="eyebrow">ON THE CALENDAR</span><h2>Next exam</h2></div><Link href="/planner" className="text-link" data-testid="link-exam-planner">Planner <ArrowRight size={14}/></Link></div>
        {next?<div className="exam-feature" data-testid={`card-next-exam-${next.id}`}><div className="exam-date"><strong>{daysUntil(next.date)}</strong><span>{daysUntil(next.date)===1?'DAY':'DAYS'} LEFT</span></div><div><h3>{next.name}</h3><p>{subjectName(store,next.subjectId)} · {new Date(`${next.date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</p></div><div className="exam-spark"><ArrowUp size={18}/></div></div>:<CompactEmpty icon={<CalendarDays/>} title="A clear horizon" text="Add an exam to keep your countdown in view." action="Add an exam" href="/planner"/>}
      </section>
    </div>
    <section className="panel timetable-panel"><div className="section-title"><div><span className="eyebrow">YOUR ROUTINE</span><h2>Today’s timetable</h2></div><Link href="/planner" className="text-link" data-testid="link-timetable">View week <ArrowRight size={14}/></Link></div>
      {timetable.length?<div className="timeline">{timetable.map(t=><div className="timeline-row" key={t.id} data-testid={`row-timetable-${t.id}`}><div className="timeline-time">{t.startTime}<small>{t.endTime}</small></div><span className="timeline-dot"/><div className="timeline-block"><strong>{subjectName(store,t.subjectId)}</strong><span>{t.lessonId?store.lessons.find(l=>l.id===t.lessonId)?.name:'Study time'}</span></div></div>)}</div>:<CompactEmpty icon={<AlarmClock/>} title="Nothing scheduled today" text="Shape your week with a study block that fits." action="Build a timetable" href="/planner"/>}
    </section>
    {store.reminders.filter(r=>!r.completed&&new Date(r.dueAt).getTime()<=Date.now()).length>0&&<ReminderBanner reminders={store.reminders.filter(r=>!r.completed&&new Date(r.dueAt).getTime()<=Date.now())} store={store}/>}
  </>;
}
function Metric({icon,label,value,note,color,progress}:{icon:any;label:string;value:string;note:string;color:string;progress?:number}){
  return <div className={`metric-card metric-${color}`} data-testid={`metric-${idTest(label)}`}><div className="metric-top"><span className="metric-icon">{icon}</span>{progress!==undefined&&<span className="metric-ring">{progress}%</span>}</div><div className="metric-label">{label}</div><strong className="metric-value">{value}</strong><span className="metric-note">{note}</span>{progress!==undefined&&<div className="progress-track"><i style={{width:`${progress}%`}}/></div>}</div>;
}
function CompactEmpty({icon,title,text,action,href}:{icon:any;title:string;text:string;action:string;href:string}){
  return <div className="compact-empty"><span className="compact-empty-icon">{icon}</span><div><strong>{title}</strong><p>{text}</p><Link href={href} className="text-link" data-testid={`link-${idTest(action)}`}>{action}<ArrowRight size={13}/></Link></div></div>;
}
function subjectName(s:Store,id:string|null){return id?s.subjects.find(x=>x.id===id)?.name||'Removed subject':'Personal';}
function daysUntil(date:string){return Math.ceil((new Date(`${date}T00:00:00`).getTime()-new Date(`${localDate()}T00:00:00`).getTime())/86400000);}
function calcStreak(sessions:StudySession[]){
  const dates=new Set(sessions.filter(s=>s.durationSeconds>0).map(s=>localDate(new Date(s.startedAt))));
  let cursor=new Date();if(!dates.has(localDate(cursor)))cursor.setDate(cursor.getDate()-1);let n=0;
  while(dates.has(localDate(cursor))){n++;cursor.setDate(cursor.getDate()-1);}return n;
}
function TaskRow({task,store,setStore,notify,askDelete}:Pick<Shared,'store'|'setStore'|'notify'|'askDelete'>&{task:Task}){
  return <div className={`task-row ${task.completed?'is-done':''}`} data-testid={`row-task-${task.id}`}><button className="check-button" aria-label={task.completed?'Reopen task':'Complete task'} onClick={()=>{setStore(s=>({...s,tasks:s.tasks.map(x=>x.id===task.id?{...x,completed:!x.completed}:x)}));notify(task.completed?'Task reopened':'Task completed');}} data-testid={`button-toggle-task-${task.id}`}>{task.completed?<Check size={14}/>:<Circle size={16}/>}</button><div className="task-main"><strong>{task.title}</strong><small>{task.type} · {subjectName(store,task.subjectId)}</small></div><button className="icon-button tiny" onClick={()=>askDelete('tasks',task.id,task.title)} aria-label="Delete task" data-testid={`button-delete-task-${task.id}`}><Trash2 size={15}/></button></div>;
}
function ReminderBanner({reminders,store}:{reminders:Reminder[];store:Store}){
  return <div className="reminder-banner"><Bell size={18}/><div><strong>{reminders.length===1?'A reminder is due':'Reminders are due'}</strong><span>{reminders.map(r=>r.title).join(' · ')}{reminders[0]?.subjectId?` · ${subjectName(store,reminders[0].subjectId)}`:''}</span></div><Link href="/planner" className="text-link" data-testid="link-reminders">Review <ArrowRight size={14}/></Link></div>;
}
function StudyPage(p:Shared){
  const {store}=p;const [expanded,setExpanded]=useState<string[]>([]);const [studyTab,setStudyTab]=useState<'syllabus'|'cards'|'quizzes'|'timer'>('syllabus');
  const toggle=(id:string)=>setExpanded(x=>x.includes(id)?x.filter(y=>y!==id):[...x,id]);
  return <><PageHeading eyebrow="YOUR LEARNING SPACE" title="Study, your way." description="Build your syllabus, then pick a small next step." action={{label:'Add a subject',onClick:p.addSubject}}/>
    <div className="tab-row" role="tablist">{[['syllabus','Syllabus'],['cards','Flashcards'],['quizzes','Quizzes'],['timer','Focus timer']].map(([k,l])=><button key={k} className={`tab-button ${studyTab===k?'selected':''}`} onClick={()=>setStudyTab(k as any)} data-testid={`tab-study-${k}`}>{l}{k==='cards'&&store.flashcards.length>0&&<span className="tab-count">{store.flashcards.length}</span>}</button>)}</div>
    {studyTab==='syllabus'&&<section className="syllabus-area">{store.subjects.length===0?<Empty kind="subjects" onAdd={p.addSubject} label="Add your first subject"/>:<div className="subject-stack">{[...store.subjects].sort((a,b)=>a.order-b.order).map((s,si)=>{const lessons=store.lessons.filter(l=>l.subjectId===s.id).sort((a,b)=>a.order-b.order),st=store.topics.filter(t=>t.subjectId===s.id),done=st.filter(t=>t.status==='completed').length;return <article className="subject-card" key={s.id} data-testid={`card-subject-${s.id}`}><div className="subject-head"><button className={`collapse-arrow ${expanded.includes(s.id)?'open':''}`} onClick={()=>toggle(s.id)} aria-label="Toggle subject"><ChevronRight size={17}/></button><span className="subject-letter">{s.name.slice(0,1).toUpperCase()}</span><button className="subject-title-button" onClick={()=>toggle(s.id)}><strong>{s.name}</strong><small>{lessons.length} {lessons.length===1?'lesson':'lessons'} · {done}/{st.length} topics</small></button><div className="subject-progress"><div className="progress-track"><i style={{width:`${pct(done,st.length)}%`}}/></div><span>{pct(done,st.length)}%</span></div><div className="row-actions"><button className="icon-button tiny" onClick={()=>p.reorder('subjects',s.id,-1)} aria-label="Move subject up" data-testid={`button-subject-up-${s.id}`}><ArrowUp size={14}/></button><button className="icon-button tiny" onClick={()=>p.reorder('subjects',s.id,1)} aria-label="Move subject down" data-testid={`button-subject-down-${s.id}`}><ArrowDown size={14}/></button><button className="icon-button tiny" onClick={()=>p.editSubject(s)} aria-label="Edit subject" data-testid={`button-edit-subject-${s.id}`}><Pencil size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('subjects',s.id,s.name)} aria-label="Delete subject" data-testid={`button-delete-subject-${s.id}`}><Trash2 size={14}/></button></div></div>{expanded.includes(s.id)&&<div className="subject-content">{lessons.map((l,li)=>{const topics=store.topics.filter(t=>t.lessonId===l.id);return <div className="lesson-block" key={l.id} data-testid={`card-lesson-${l.id}`}><div className="lesson-head"><button className={`collapse-arrow small-arrow ${expanded.includes(l.id)?'open':''}`} onClick={()=>toggle(l.id)} aria-label="Toggle lesson"><ChevronRight size={15}/></button><span className="lesson-marker">{String(li+1).padStart(2,'0')}</span><button className="lesson-title-button" onClick={()=>toggle(l.id)}><strong>{l.name}</strong><small>{topics.length} {topics.length===1?'topic':'topics'} · {pct(topics.filter(t=>t.status==='completed').length,topics.length)}% complete</small></button><button className="icon-button tiny" onClick={()=>p.reorder('lessons',l.id,-1)} aria-label="Move lesson up" data-testid={`button-lesson-up-${l.id}`}><ArrowUp size={13}/></button><button className="icon-button tiny" onClick={()=>p.reorder('lessons',l.id,1)} aria-label="Move lesson down" data-testid={`button-lesson-down-${l.id}`}><ArrowDown size={13}/></button><button className="icon-button tiny" onClick={()=>p.editLesson(l)} aria-label="Edit lesson" data-testid={`button-edit-lesson-${l.id}`}><Pencil size={13}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('lessons',l.id,l.name)} aria-label="Delete lesson" data-testid={`button-delete-lesson-${l.id}`}><Trash2 size={13}/></button></div>{expanded.includes(l.id)&&<div className="topic-list">{topics.map(t=><TopicRow key={t.id} topic={t} {...p}/>)}<button className="inline-add topic-add" onClick={()=>p.addTopic(s,l)} data-testid={`button-add-topic-${l.id}`}><Plus size={14}/>Add topic</button></div>}</div>})}<button className="inline-add" onClick={()=>p.addLesson(s)} data-testid={`button-add-lesson-${s.id}`}><Plus size={15}/>Add a lesson</button></div>}</article>})}</div>}</section>}
    {studyTab==='cards'&&<Flashcards p={p}/>}
    {studyTab==='quizzes'&&<Quizzes p={p}/>}
    {studyTab==='timer'&&<FocusTimer p={p}/>}
  </>;
}
function TopicRow({topic:t,store,setStore,notify,editTopic,askDelete,reorderTopic}:Shared&{topic:Topic}){
  const cycle:TopicStatus=t.status==='not_started'?'in_progress':t.status==='in_progress'?'completed':'not_started';
  return <div className="topic-row" data-testid={`row-topic-${t.id}`}><button className={`topic-status status-${t.status}`} onClick={()=>{setStore(s=>({...s,topics:s.topics.map(x=>x.id===t.id?{...x,status:cycle}:x)}));notify(cycle==='completed'?'Topic completed':cycle==='in_progress'?'Topic in progress':'Topic reset');}} aria-label={`Change status for ${t.name}`} data-testid={`button-topic-status-${t.id}`}>{t.status==='completed'?<Check size={13}/>:t.status==='in_progress'?<span className="status-half"/>:<span/>}</button><span className="topic-name">{t.name}</span><span className={`priority-tag priority-${t.priority}`}>{t.priority}</span><span className={`topic-state-label state-label-${t.status}`}>{t.status.replace('_',' ')}</span><button className="icon-button tiny" onClick={()=>reorderTopic(t.id,-1)} aria-label="Move topic up" data-testid={`button-topic-up-${t.id}`}><ArrowUp size={12}/></button><button className="icon-button tiny" onClick={()=>reorderTopic(t.id,1)} aria-label="Move topic down" data-testid={`button-topic-down-${t.id}`}><ArrowDown size={12}/></button><button className="icon-button tiny" onClick={()=>editTopic(t)} aria-label="Edit topic" data-testid={`button-edit-topic-${t.id}`}><Pencil size={13}/></button><button className="icon-button tiny danger-hover" onClick={()=>askDelete('topics',t.id,t.name)} aria-label="Delete topic" data-testid={`button-delete-topic-${t.id}`}><Trash2 size={13}/></button></div>;
}
function Flashcards({p}:{p:Shared}){
  const {store}=p;const [filter,setFilter]=useState('');const [lessonFilter,setLessonFilter]=useState('');const [revising,setRevising]=useState(false);const [index,setIndex]=useState(0);const [revealed,setRevealed]=useState(false);
  const cards=store.flashcards.filter(c=>(!filter||c.subjectId===filter)&&(!lessonFilter||c.lessonId===lessonFilter));
  const create=()=>p.openForm({title:'Create a flashcard',fields:[{key:'question',label:'Front · question or prompt',kind:'textarea',required:true},{key:'answer',label:'Back · answer',kind:'textarea',required:true},p.formSubject(),{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],onSave:v=>p.save('flashcards',{question:v.question,answer:v.answer,subjectId:v.subjectId||null,lessonId:v.lessonId||null})});
  const revise=()=>{setIndex(0);setRevealed(false);setRevising(true);};
  const card=cards[index];
  return <div className="study-tool"><div className="tool-header"><div><span className="eyebrow">RECALL PRACTICE</span><h2>Flashcards <span className="soft-count">{store.flashcards.length}</span></h2><p>Make a card, then see what sticks.</p></div><div className="tool-actions">{store.flashcards.length>0&&<button className="button button-secondary" onClick={revise} data-testid="button-revise-flashcards"><RotateCcw size={15}/>Study cards</button>}<button className="button button-primary" onClick={create} data-testid="button-add-flashcard"><Plus size={16}/>New flashcard</button></div></div>
    <div className="filter-strip"><label className="select-wrap"><BookOpen size={15}/><select value={filter} onChange={e=>{setFilter(e.target.value);setLessonFilter('');setIndex(0);}} data-testid="filter-flashcard-subject"><option value="">All subjects</option>{store.subjects.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><ChevronDown size={14}/></label><label className="select-wrap"><select value={lessonFilter} onChange={e=>{setLessonFilter(e.target.value);setIndex(0);}} data-testid="filter-flashcard-lesson"><option value="">All lessons</option>{store.lessons.filter(l=>!filter||l.subjectId===filter).map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select><ChevronDown size={14}/></label><span className="filter-result">{cards.length} {cards.length===1?'card':'cards'}</span></div>
    {revising&&card?<div className="revision-stage"><button className="revision-close icon-button" onClick={()=>setRevising(false)} aria-label="Close revision" data-testid="button-close-revision"><X size={18}/></button><span className="eyebrow">CARD {index+1} OF {cards.length}</span><div className={`flashcard ${revealed?'revealed':''}`} onClick={()=>setRevealed(x=>!x)} role="button" tabIndex={0} onKeyDown={e=>e.key==='Enter'&&setRevealed(x=>!x)} data-testid={`flashcard-current-${card.id}`}><span>{revealed?'ANSWER':'PROMPT'}</span><strong>{revealed?card.answer:card.question}</strong><small>{revealed?'Tap to return to prompt':'Tap to reveal answer'}</small></div><div className="revision-controls"><button className="button button-secondary" onClick={()=>{setIndex(x=>(x-1+cards.length)%cards.length);setRevealed(false);}} data-testid="button-card-previous"><ChevronLeft size={16}/>Previous</button><button className="button button-primary" onClick={()=>{setIndex(x=>(x+1)%cards.length);setRevealed(false);}} data-testid="button-card-next">Next card<ChevronRight size={16}/></button></div></div>:store.flashcards.length===0?<Empty kind="notes" onAdd={create} label="Create a flashcard" title="Nothing to revise yet" body="Make a flashcard from a question you want to remember. Your first card starts your own revision set."/>:cards.length===0?<div className="soft-empty"><Search size={21}/><strong>No cards for this subject yet</strong><p>Try a different filter or make a new card.</p></div>:<div className="resource-list">{cards.map(c=><article className="resource-card flashcard-row" key={c.id} data-testid={`card-flashcard-${c.id}`}><div className="resource-accent"/><div className="resource-body"><span className="eyebrow">{subjectName(store,c.subjectId)}{c.lessonId?` · ${store.lessons.find(l=>l.id===c.lessonId)?.name||''}`:''}</span><h3>{c.question}</h3><p>{c.answer}</p></div><button className="icon-button tiny" onClick={()=>p.openForm({title:'Edit flashcard',initial:{question:c.question,answer:c.answer,subjectId:c.subjectId||'',lessonId:c.lessonId||''},fields:[{key:'question',label:'Question',kind:'textarea',required:true},{key:'answer',label:'Answer',kind:'textarea',required:true},p.formSubject(),{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],onSave:v=>p.save('flashcards',{question:v.question,answer:v.answer,subjectId:v.subjectId||null,lessonId:v.lessonId||null},c.id)})} aria-label="Edit flashcard" data-testid={`button-edit-flashcard-${c.id}`}><Pencil size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('flashcards',c.id,c.question)} aria-label="Delete flashcard" data-testid={`button-delete-flashcard-${c.id}`}><Trash2 size={14}/></button></article>)}</div>}
  </div>;
}
function Quizzes({p}:{p:Shared}){
  const {store}=p;const [taking,setTaking]=useState<Quiz|null>(null);const [answers,setAnswers]=useState<number[]>([]);const [result,setResult]=useState<{score:number;total:number}|null>(null);
  const editTitle=(q:Quiz)=>p.openForm({title:'Edit quiz',initial:{title:q.title},fields:[{key:'title',label:'Quiz title',required:true}],onSave:v=>p.save('quizzes',{title:v.title.trim()},q.id)});
  const appendQuestion=(q:Quiz)=>p.openForm({title:`Add a question · ${q.title}`,fields:[{key:'prompt',label:'Question',kind:'textarea',required:true},{key:'a',label:'Option 1',required:true},{key:'b',label:'Option 2',required:true},{key:'c',label:'Option 3',required:true},{key:'d',label:'Option 4',required:true},{key:'correctIndex',label:'Correct answer',kind:'select',options:[{value:'0',label:'Option 1'},{value:'1',label:'Option 2'},{value:'2',label:'Option 3'},{value:'3',label:'Option 4'}]}],onSave:v=>p.save('quizzes',{questions:[...q.questions,{prompt:v.prompt,options:[v.a,v.b,v.c,v.d],correctIndex:Number(v.correctIndex||0)}]},q.id)});
  const create=()=>p.openForm({title:'Build a quiz',fields:[{key:'title',label:'Quiz title',required:true,placeholder:'Give this quiz a name'},p.formSubject(),{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]},{key:'prompt',label:'Question',kind:'textarea',required:true},{key:'a',label:'Option 1',required:true},{key:'b',label:'Option 2',required:true},{key:'c',label:'Option 3',required:true},{key:'d',label:'Option 4',required:true},{key:'correctIndex',label:'Correct answer',kind:'select',options:[{value:'0',label:'Option 1'},{value:'1',label:'Option 2'},{value:'2',label:'Option 3'},{value:'3',label:'Option 4'}]}],onSave:v=>p.save('quizzes',{title:v.title,subjectId:v.subjectId||null,lessonId:v.lessonId||null,questions:[{prompt:v.prompt,options:[v.a,v.b,v.c,v.d],correctIndex:Number(v.correctIndex||0)}],attempts:[]})});
  const start=(q:Quiz)=>{setTaking(q);setAnswers(q.questions.map(()=>-1));setResult(null);};
  const finish=()=>{if(!taking)return;const score=taking.questions.reduce((n,q,i)=>n+(answers[i]===q.correctIndex?1:0),0);const attempt={score,total:taking.questions.length,completedAt:new Date().toISOString()};p.setStore(s=>({...s,quizzes:s.quizzes.map(q=>q.id===taking.id?{...q,attempts:[...q.attempts,attempt]}:q)}));p.notify(`Quiz complete · ${score} of ${taking.questions.length}`);setResult({score,total:taking.questions.length});};
  if(taking)return <div className="quiz-take panel"><button className="back-link" onClick={()=>setTaking(null)} data-testid="button-exit-quiz"><ArrowLeft size={15}/>Back to quizzes</button><span className="eyebrow">QUIZ IN PROGRESS</span><h2>{taking.title}</h2>{result?<div className="quiz-result"><div className="result-medallion"><CheckCircle2 size={34}/></div><h3>{result.score} <span>/ {result.total}</span></h3><p>{result.score===result.total?'A perfect round. Take a moment to enjoy it.':'Nice work showing up. Every attempt helps it stick.'}</p><button className="button button-primary" onClick={()=>setTaking(null)} data-testid="button-quiz-done">Done</button></div>:<><div className="quiz-progress"><span>{answers.filter(a=>a>=0).length} of {taking.questions.length} answered</span><div className="progress-track"><i style={{width:`${answers.filter(a=>a>=0).length/taking.questions.length*100}%`}}/></div></div>{taking.questions.map((q,qi)=><div className="question-block" key={qi}><span className="question-number">QUESTION {String(qi+1).padStart(2,'0')}</span><h3>{q.prompt}</h3><div className="option-grid">{q.options.map((o,oi)=><button key={oi} className={`answer-option ${answers[qi]===oi?'chosen':''}`} onClick={()=>setAnswers(a=>a.map((x,i)=>i===qi?oi:x))} data-testid={`button-quiz-answer-${qi}-${oi}`}><span>{String.fromCharCode(65+oi)}</span>{o}</button>)}</div></div>)}<button className="button button-primary" disabled={answers.some(a=>a<0)} onClick={finish} data-testid="button-submit-quiz">Finish quiz <ArrowRight size={15}/></button></>}</div>;
  return <div className="study-tool"><div className="tool-header"><div><span className="eyebrow">CHECK WHAT YOU KNOW</span><h2>Your quizzes <span className="soft-count">{store.quizzes.length}</span></h2><p>Write your own questions and keep every attempt.</p></div><button className="button button-primary" onClick={create} data-testid="button-create-quiz"><Plus size={16}/>Create a quiz</button></div>{store.quizzes.length===0?<Empty kind="notes" onAdd={create} label="Build your quiz" title="Your first quiz starts with one question" body="Write four choices, mark the right one, and add more questions whenever you like."/>:<div className="quiz-list">{store.quizzes.map(q=>{const last=q.attempts[q.attempts.length-1];return <article className="quiz-card" key={q.id} data-testid={`card-quiz-${q.id}`}><div className="quiz-mark"><Target size={19}/></div><div className="quiz-info"><h3>{q.title}</h3><p>{q.questions.length} {q.questions.length===1?'question':'questions'} · {subjectName(store,q.subjectId)}</p><span>{last?`Last score ${last.score}/${last.total} · ${q.attempts.length} ${q.attempts.length===1?'attempt':'attempts'}`:'Not attempted yet'}</span></div><button className="icon-button tiny" onClick={()=>editTitle(q)} aria-label="Edit quiz title" data-testid={`button-edit-quiz-${q.id}`}><Pencil size={14}/></button><button className="icon-button tiny" onClick={()=>appendQuestion(q)} aria-label="Add a question" data-testid={`button-add-question-${q.id}`}><Plus size={15}/></button><button className="button button-primary button-small" onClick={()=>start(q)} data-testid={`button-take-quiz-${q.id}`}>Take quiz <ArrowRight size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('quizzes',q.id,q.title)} aria-label="Delete quiz" data-testid={`button-delete-quiz-${q.id}`}><Trash2 size={14}/></button></article>})}</div>}</div>;
}
function FocusTimer({p}:{p:Shared}){
  const [duration,setDuration]=useState(p.store.preferences.focusMinutes);const [remaining,setRemaining]=useState(duration*60);const [running,setRunning]=useState(false);const [subject,setSubject]=useState('');const [phase,setPhase]=useState<'focus'|'break'>('focus');const segmentStarted=useRef(Date.now());
  useEffect(()=>{if(!running)return;const t=setInterval(()=>setRemaining(r=>Math.max(0,r-1)),1000);return()=>clearInterval(t);},[running]);
  useEffect(()=>{if(remaining===0&&running){setRunning(false);if(phase==='focus'){const elapsed=Math.max(1,Math.min(duration*60,Math.floor((Date.now()-segmentStarted.current)/1000)));p.setStore(s=>({...s,sessions:[...s.sessions,{id:uid(),startedAt:new Date(segmentStarted.current).toISOString(),durationSeconds:elapsed,subjectId:subject||null}]}));setPhase('break');setRemaining(p.store.preferences.breakMinutes*60);p.notify('Focus session saved. Break time.');}else{setPhase('focus');setRemaining(duration*60);p.notify('Break complete. Ready when you are.');}}},[remaining,running]);
  const setMinutes=(m:number)=>{setDuration(m);if(phase==='focus')setRemaining(m*60);setRunning(false);};
  const reset=()=>{setRunning(false);setRemaining((phase==='break'?p.store.preferences.breakMinutes:duration)*60);};
  const pause=()=>{if(phase==='focus'){const elapsed=Math.max(0,Math.floor((Date.now()-segmentStarted.current)/1000));if(elapsed>0)p.setStore(s=>({...s,sessions:[...s.sessions,{id:uid(),startedAt:new Date(segmentStarted.current).toISOString(),durationSeconds:elapsed,subjectId:subject||null}]}));p.notify(elapsed?'Elapsed focus time saved':'Timer paused');}setRunning(false);};
  return <div className="timer-layout"><section className="timer-card"><div className="timer-head"><span className="eyebrow">A LITTLE FOCUS GOES A LONG WAY</span><h2>{phase==='focus'?'Find your flow.':'Take a real pause.'}</h2><p>{phase==='focus'?'Choose a focus length, then let everything else wait.':'Step away, stretch, and let your thoughts settle.'}</p></div><div className="timer-dial"><div className="dial-inner"><span className="dial-label">{running?phase==='focus'?'FOCUSING':'BREAK TIME':phase==='focus'?'READY WHEN YOU ARE':'READY FOR A BREAK'}</span><strong>{String(Math.floor(remaining/60)).padStart(2,'0')}<i>:</i>{String(remaining%60).padStart(2,'0')}</strong><span className="dial-duration">{phase==='break'?p.store.preferences.breakMinutes:duration} minute {phase}</span></div><svg viewBox="0 0 200 200" aria-hidden="true"><circle cx="100" cy="100" r="91"/><circle className="dial-progress" cx="100" cy="100" r="91" style={{strokeDashoffset:`${572*(1-remaining/((phase==='break'?p.store.preferences.breakMinutes:duration)*60))}`}}/></svg></div><div className="timer-presets">{[15,25,45].map(m=><button key={m} className={duration===m?'chosen':''} onClick={()=>setMinutes(m)} data-testid={`button-timer-${m}`}>{m} min</button>)}<label className="custom-time">Custom <input type="number" min="1" max="180" value={duration} onChange={e=>setMinutes(Math.min(180,Math.max(1,Number(e.target.value)||1)))} data-testid="input-custom-duration"/></label></div><label className="timer-subject"><span>Working on</span><select value={subject} onChange={e=>setSubject(e.target.value)} data-testid="select-timer-subject"><option value="">No subject selected</option>{p.store.subjects.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><ChevronDown size={14}/></label><div className="timer-buttons">{running?<button className="button button-primary timer-main-button" onClick={pause} data-testid="button-pause-timer"><Pause size={17}/>Pause session</button>:<button className="button button-primary timer-main-button" onClick={()=>{if(remaining===0)setRemaining((phase==='break'?p.store.preferences.breakMinutes:duration)*60);segmentStarted.current=Date.now();setRunning(true);}} data-testid="button-start-timer"><Play size={17}/>{phase==='break'?'Start break':'Start focusing'}</button>}<button className="icon-button reset-button" onClick={reset} aria-label="Reset timer" data-testid="button-reset-timer"><RotateCcw size={17}/></button></div><p className="timer-footnote"><CheckCircle2 size={14}/>{phase==='focus'?'Elapsed focus time is saved to your study log.':'Breaks are for you; only focus time is tracked.'}</p></section><aside className="timer-aside"><div className="timer-aside-icon"><Zap size={21}/></div><span className="eyebrow">A GENTLE RHYTHM</span><h3>Focus, then breathe.</h3><p>The classic Pomodoro rhythm is {p.store.preferences.focusMinutes} minutes of focus followed by {p.store.preferences.breakMinutes} minutes away from the screen.</p><button className="text-link" onClick={()=>p.openForm({title:'Timer defaults',initial:{focusMinutes:p.store.preferences.focusMinutes,breakMinutes:p.store.preferences.breakMinutes},fields:[{key:'focusMinutes',label:'Focus minutes',kind:'number'},{key:'breakMinutes',label:'Break minutes',kind:'number'}],onSave:v=>{p.setStore(s=>({...s,preferences:{...s.preferences,focusMinutes:Math.max(1,Number(v.focusMinutes)||25),breakMinutes:Math.max(1,Number(v.breakMinutes)||5)}}));p.notify('Timer defaults updated');}})} data-testid="button-edit-timer-defaults">Adjust your defaults <ArrowRight size={14}/></button><div className="focus-today"><span>FOCUS TODAY</span><strong>{Math.floor(p.store.sessions.filter(s=>localDate(new Date(s.startedAt))===localDate()).reduce((n,s)=>n+s.durationSeconds,0)/60)}<small> minutes</small></strong></div></aside></div>;
}
function NotesPage(p:Shared){
  const {store}=p;const [query,setQuery]=useState('');const [subject,setSubject]=useState('');const [lesson,setLesson]=useState('');const [sort,setSort]=useState<'recent'|'oldest'>('recent');
  const add=()=>p.openForm({title:'Write a note',fields:[{key:'title',label:'Note title',required:true,placeholder:'A clear name for this thought'},{key:'body',label:'Your note',kind:'textarea',required:true,placeholder:'Capture what you want to remember…'},p.formSubject(),{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],onSave:v=>p.save('notes',{title:v.title.trim(),body:v.body,subjectId:v.subjectId||null,lessonId:v.lessonId||null,updatedAt:new Date().toISOString()})});
  const notes=store.notes.filter(n=>(!subject||n.subjectId===subject)&&(!lesson||n.lessonId===lesson)&&(!query||`${n.title} ${n.body}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>sort==='recent'?b.updatedAt.localeCompare(a.updatedAt):a.updatedAt.localeCompare(b.updatedAt));
  const edit=(n:Note)=>p.openForm({title:'Edit note',initial:{title:n.title,body:n.body,subjectId:n.subjectId||'',lessonId:n.lessonId||''},fields:[{key:'title',label:'Note title',required:true},{key:'body',label:'Your note',kind:'textarea',required:true},p.formSubject(),{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],onSave:v=>p.save('notes',{title:v.title.trim(),body:v.body,subjectId:v.subjectId||null,lessonId:v.lessonId||null,updatedAt:new Date().toISOString()},n.id)});
  return <><PageHeading eyebrow="YOUR THOUGHTS, KEPT CLOSE" title="Notes." description="A searchable place for the things you want to remember." action={{label:'Write a note',onClick:add}}/>
    <div className="filter-toolbar"><label className="search-field"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search your notes" data-testid="input-search-notes"/>{query&&<button onClick={()=>setQuery('')} aria-label="Clear search" data-testid="button-clear-search"><X size={14}/></button>}</label><label className="select-wrap"><BookOpen size={15}/><select value={subject} onChange={e=>{setSubject(e.target.value);setLesson('');}} data-testid="filter-notes-subject"><option value="">All subjects</option>{store.subjects.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><ChevronDown size={14}/></label><label className="select-wrap"><select value={lesson} onChange={e=>setLesson(e.target.value)} data-testid="filter-notes-lesson"><option value="">All lessons</option>{store.lessons.filter(l=>!subject||l.subjectId===subject).map(l=><option value={l.id} key={l.id}>{l.name}</option>)}</select><ChevronDown size={14}/></label><label className="select-wrap sort-select"><select value={sort} onChange={e=>setSort(e.target.value as any)} data-testid="select-notes-sort"><option value="recent">Recently updated</option><option value="oldest">Oldest first</option></select><ChevronDown size={14}/></label></div>
    {notes.length===0?store.notes.length===0?<Empty kind="notes" onAdd={add} label="Write your first note"/>:<div className="soft-empty"><Search size={22}/><strong>No notes match that search</strong><p>Try another phrase or clear your filters.</p><button className="text-link" onClick={()=>{setQuery('');setSubject('');setLesson('');}} data-testid="button-clear-note-filters">Clear filters <X size={14}/></button></div>:<div className="notes-grid">{notes.map(n=><article className="note-card" key={n.id} data-testid={`card-note-${n.id}`}><div className="note-card-top"><span className="note-subject">{subjectName(store,n.subjectId)}{n.lessonId&&` · ${store.lessons.find(l=>l.id===n.lessonId)?.name||''}`}</span><div className="row-actions"><button className="icon-button tiny" onClick={()=>edit(n)} aria-label="Edit note" data-testid={`button-edit-note-${n.id}`}><Pencil size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('notes',n.id,n.title)} aria-label="Delete note" data-testid={`button-delete-note-${n.id}`}><Trash2 size={14}/></button></div></div><h3>{n.title}</h3><p>{n.body}</p><footer>Updated {new Date(n.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</footer></article>)}</div>}
    <div className="notes-footer"><span>{notes.length} {notes.length===1?'note':'notes'} in your space</span><span>Only you can see these</span></div>
  </>;
}
function PlannerPage(p:Shared){
  const {store}=p;const [plannerTab,setPlannerTab]=useState<'week'|'exams'|'tasks'|'reminders'|'smart'>('week');const [weekDay,setWeekDay]=useState(dayIndex());const [taskMode,setTaskMode]=useState<'pending'|'completed'|'all'>('pending');const [available,setAvailable]=useState(60);const [plan,setPlan]=useState<Topic[]|null>(null);
  const addTimetable=()=>p.openForm({title:'Add a study block',fields:[{key:'weekday',label:'Day',kind:'select',options:days.map((d,i)=>({value:String(i),label:d}))},{key:'startTime',label:'Starts',kind:'time',required:true},{key:'endTime',label:'Ends',kind:'time',required:true},{key:'subjectId',label:'Subject',kind:'select',options:p.store.subjects.map(s=>({value:s.id,label:s.name})),required:true},{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],initial:{weekday:String(weekDay),startTime:'09:00',endTime:'10:00'},onSave:v=>p.save('timetable',{weekday:Number(v.weekday),startTime:v.startTime,endTime:v.endTime,subjectId:v.subjectId,lessonId:v.lessonId||null})});
  const editTimetable=(t:TimetableEntry)=>p.openForm({title:'Edit study block',initial:{weekday:String(t.weekday),startTime:t.startTime,endTime:t.endTime,subjectId:t.subjectId,lessonId:t.lessonId||''},fields:[{key:'weekday',label:'Day',kind:'select',options:days.map((d,i)=>({value:String(i),label:d}))},{key:'startTime',label:'Starts',kind:'time',required:true},{key:'endTime',label:'Ends',kind:'time',required:true},{key:'subjectId',label:'Subject',kind:'select',options:selectSubject(p.store),required:true},{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],onSave:v=>p.save('timetable',{weekday:Number(v.weekday),startTime:v.startTime,endTime:v.endTime,subjectId:v.subjectId,lessonId:v.lessonId||null},t.id)});
  const addExam=()=>p.openForm({title:'Add an exam',fields:[{key:'name',label:'Exam name',required:true,placeholder:'Name of the exam'}, {key:'subjectId',label:'Subject',kind:'select',options:selectSubject(store),required:true},{key:'date',label:'Exam date',kind:'date',required:true}],onSave:v=>p.save('exams',{name:v.name.trim(),subjectId:v.subjectId,date:v.date})});
  const editExam=(e:Exam)=>p.openForm({title:'Edit exam',initial:{name:e.name,subjectId:e.subjectId,date:e.date},fields:[{key:'name',label:'Exam name',required:true},{key:'subjectId',label:'Subject',kind:'select',options:selectSubject(store),required:true},{key:'date',label:'Exam date',kind:'date',required:true}],onSave:v=>p.save('exams',{name:v.name.trim(),subjectId:v.subjectId,date:v.date},e.id)});
  const addTask=()=>p.openForm({title:'Add a study task',fields:[{key:'title',label:'Task',required:true,placeholder:'What needs doing?'},{key:'type',label:'Category',kind:'select',options:[['homework','Homework'],['assignment','Assignment'],['revision','Revision'],['other','Other']].map(([value,label])=>({value,label}))},{key:'dueDate',label:'Due date',kind:'date',required:true},p.formSubject(),{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],initial:{type:'homework',dueDate:localDate()},onSave:v=>p.save('tasks',{title:v.title.trim(),type:v.type,dueDate:v.dueDate,subjectId:v.subjectId||null,lessonId:v.lessonId||null,completed:false})});
  const editTask=(t:Task)=>p.openForm({title:'Edit task',initial:{title:t.title,type:t.type,dueDate:t.dueDate,subjectId:t.subjectId||'',lessonId:t.lessonId||''},fields:[{key:'title',label:'Task',required:true},{key:'type',label:'Category',kind:'select',options:[['homework','Homework'],['assignment','Assignment'],['revision','Revision'],['other','Other']].map(([value,label])=>({value,label}))},{key:'dueDate',label:'Due date',kind:'date',required:true},p.formSubject(),{key:'lessonId',label:'Lesson',kind:'select',options:[{value:'',label:'No lesson'},...store.lessons.map(l=>({value:l.id,label:l.name,subjectId:l.subjectId}))]}],onSave:v=>p.save('tasks',{title:v.title.trim(),type:v.type,dueDate:v.dueDate,subjectId:v.subjectId||null,lessonId:v.lessonId||null},t.id)});
  const addReminder=()=>p.openForm({title:'Create a reminder',fields:[{key:'title',label:'Reminder',required:true},{key:'type',label:'Category',kind:'select',options:[['study','Study'],['exam','Exam'],['assignment','Assignment'],['revision','Revision']].map(([value,label])=>({value,label}))},{key:'dueAt',label:'When',kind:'datetime-local',required:true},p.formSubject()],initial:{type:'study',dueAt:localDateTime()},onSave:v=>p.save('reminders',{title:v.title.trim(),type:v.type,dueAt:v.dueAt,subjectId:v.subjectId||null,completed:false})});
  const editReminder=(r:Reminder)=>p.openForm({title:'Edit reminder',initial:{title:r.title,type:r.type,dueAt:r.dueAt,subjectId:r.subjectId||''},fields:[{key:'title',label:'Reminder',required:true},{key:'type',label:'Category',kind:'select',options:[['study','Study'],['exam','Exam'],['assignment','Assignment'],['revision','Revision']].map(([value,label])=>({value,label}))},{key:'dueAt',label:'When',kind:'datetime-local',required:true},p.formSubject()],onSave:v=>p.save('reminders',{title:v.title.trim(),type:v.type,dueAt:v.dueAt,subjectId:v.subjectId||null},r.id)});
  const smartPlan=()=>{const unfinished=store.topics.filter(t=>t.status!=='completed');const sorted=[...unfinished].sort((a,b)=>{const priority={high:3,normal:2,low:1};const examA=store.exams.filter(e=>e.subjectId===a.subjectId&&e.date>=localDate()).sort((x,y)=>x.date.localeCompare(y.date))[0];const examB=store.exams.filter(e=>e.subjectId===b.subjectId&&e.date>=localDate()).sort((x,y)=>x.date.localeCompare(y.date))[0];const urgency=(e?:Exam)=>e?Math.max(0,30-daysUntil(e.date))/30:0;return (priority[b.priority]-priority[a.priority])+(urgency(examB)-urgency(examA));});let left=Math.max(0,Number(available)||0);const result:Topic[]=[];for(const t of sorted){if(left<15)break;result.push(t);left-=Math.min(30,left);}setPlan(result);};
  const tabs=[['week','Timetable'],['exams','Exams'],['tasks','Tasks'],['reminders','Reminders'],['smart','Smart plan']] as const;
  const selectedTasks=store.tasks.filter(t=>taskMode==='all'||(taskMode==='completed'?t.completed:!t.completed)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
  return <><PageHeading eyebrow="A PLAN THAT FITS YOUR LIFE" title="Planner." description="Make a little space for studying, without overthinking it."/>
    <div className="tab-row planner-tabs" role="tablist">{tabs.map(([k,l])=><button key={k} className={`tab-button ${plannerTab===k?'selected':''}`} onClick={()=>setPlannerTab(k)} data-testid={`tab-planner-${k}`}>{l}{k==='reminders'&&store.reminders.some(r=>!r.completed)?<i className="tab-dot"/>:null}</button>)}</div>
    {plannerTab==='week'&&<section className="planner-section"><div className="planner-toolbar"><div><span className="eyebrow">A ROUTINE, NOT A RULE</span><h2>Your weekly timetable</h2></div><button className="button button-primary" onClick={addTimetable} data-testid="button-add-study-block"><Plus size={16}/>Add time</button></div><div className="weekday-strip">{shortDays.map((d,i)=><button key={d} className={`weekday-pill ${weekDay===i?'selected':''} ${dayIndex()===i?'today':''}`} onClick={()=>setWeekDay(i)} data-testid={`button-weekday-${i}`}><span>{d}</span><strong>{i===dayIndex()?'Today':String(i+1).padStart(2,'0')}</strong></button>)}</div>
    {store.timetable.filter(t=>t.weekday===weekDay).length===0?<Empty kind="timetable" onAdd={addTimetable} label="Add a study block"/>:<div className="schedule-list">{store.timetable.filter(t=>t.weekday===weekDay).sort((a,b)=>a.startTime.localeCompare(b.startTime)).map(t=><article className="schedule-row" key={t.id} data-testid={`row-schedule-${t.id}`}><div className="schedule-time"><strong>{t.startTime}</strong><span>{t.endTime}</span></div><span className="schedule-rule"/><div className="schedule-content"><span className="schedule-subject-dot"/><div><strong>{subjectName(store,t.subjectId)}</strong><small>{t.lessonId?store.lessons.find(l=>l.id===t.lessonId)?.name||'Study time':'Study time'}</small></div></div><div className="row-actions"><button className="icon-button tiny" onClick={()=>editTimetable(t)} aria-label="Edit timetable entry" data-testid={`button-edit-timetable-${t.id}`}><Pencil size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('timetable',t.id,'this study block')} aria-label="Delete timetable entry" data-testid={`button-delete-timetable-${t.id}`}><Trash2 size={14}/></button></div></article>)}</div>}
    <div className="week-note"><Sparkles size={15}/><span>Your schedule is personal. Move things around whenever life does.</span></div></section>}
    {plannerTab==='exams'&&<section className="planner-section"><div className="planner-toolbar"><div><span className="eyebrow">DATES WORTH REMEMBERING</span><h2>Exam countdowns</h2></div><button className="button button-primary" onClick={addExam} data-testid="button-add-exam"><Plus size={16}/>Add exam</button></div>{store.exams.length===0?<Empty kind="exams" onAdd={addExam} label="Add an exam"/>:<div className="exam-list">{[...store.exams].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>{const n=daysUntil(e.date);return <article className={`exam-row ${n<0?'exam-past':''}`} key={e.id} data-testid={`row-exam-${e.id}`}><div className="exam-countdown"><strong>{Math.abs(n)}</strong><span>{n<0?'DAYS AGO':n===0?'TODAY':n===1?'DAY LEFT':'DAYS LEFT'}</span></div><div className="exam-main"><span className="eyebrow">{subjectName(store,e.subjectId)}</span><h3>{e.name}</h3><p>{new Date(`${e.date}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</p></div><div className="row-actions"><button className="icon-button tiny" onClick={()=>editExam(e)} aria-label="Edit exam" data-testid={`button-edit-exam-${e.id}`}><Pencil size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('exams',e.id,e.name)} aria-label="Delete exam" data-testid={`button-delete-exam-${e.id}`}><Trash2 size={14}/></button></div></article>})}</div>}</section>}
    {plannerTab==='tasks'&&<section className="planner-section"><div className="planner-toolbar"><div><span className="eyebrow">NEXT STEPS</span><h2>Study tasks</h2></div><button className="button button-primary" onClick={addTask} data-testid="button-add-task"><Plus size={16}/>Add task</button></div><div className="task-filter-tabs">{(['pending','completed','all'] as const).map(v=><button className={taskMode===v?'selected':''} onClick={()=>setTaskMode(v)} key={v} data-testid={`filter-tasks-${v}`}>{v[0].toUpperCase()+v.slice(1)} <span>{store.tasks.filter(t=>v==='all'||(v==='completed'?t.completed:!t.completed)).length}</span></button>)}</div>{selectedTasks.length===0?<Empty kind="tasks" onAdd={addTask} label="Add a task"/>:<div className="planner-task-list">{selectedTasks.map(t=><article className={`planner-task ${t.completed?'is-done':''}`} key={t.id} data-testid={`planner-task-${t.id}`}><button className="check-button" onClick={()=>{p.setStore(s=>({...s,tasks:s.tasks.map(x=>x.id===t.id?{...x,completed:!x.completed}:x)}));p.notify(t.completed?'Task reopened':'Task completed');}} aria-label={t.completed?'Reopen task':'Complete task'} data-testid={`button-toggle-planner-task-${t.id}`}>{t.completed?<Check size={14}/>:<Circle size={16}/>}</button><div className="planner-task-text"><h3>{t.title}</h3><div className="task-meta"><span className={`task-type type-${t.type}`}>{t.type}</span><span>{subjectName(store,t.subjectId)}</span><span className={t.dueDate<localDate()&&!t.completed?'overdue':''}>{t.dueDate===localDate()?'Due today':`Due ${new Date(`${t.dueDate}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'})}`}</span></div></div><div className="row-actions"><button className="icon-button tiny" onClick={()=>editTask(t)} aria-label="Edit task" data-testid={`button-edit-task-${t.id}`}><Pencil size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('tasks',t.id,t.title)} aria-label="Delete task" data-testid={`button-delete-planner-task-${t.id}`}><Trash2 size={14}/></button></div></article>)}</div>}</section>}
    {plannerTab==='reminders'&&<section className="planner-section"><div className="planner-toolbar"><div><span className="eyebrow">A KIND NUDGE</span><h2>Reminders</h2><p className="section-caption">Notifications appear here in the app. Browser alerts are used only with your permission.</p></div><button className="button button-primary" onClick={addReminder} data-testid="button-add-reminder"><Plus size={16}/>Add reminder</button></div>{'Notification'in window&&<button className="notification-permission" onClick={async()=>{const permission=await Notification.requestPermission();p.notify(permission==='granted'?'Browser notifications enabled':'Notifications not enabled');}} data-testid="button-notification-permission"><Bell size={15}/>{'Notification'in window&&Notification.permission==='granted'?'Browser permission enabled':'Allow browser notifications'}<span>Optional · no closed-tab delivery</span></button>}{store.reminders.length===0?<div className="empty-state"><div className="empty-orbit"><span className="empty-icon"><Bell size={21}/></span><i/><b/></div><h3>No reminders, no pressure</h3><p>Set yourself a gentle nudge for a study moment or a due date.</p><button className="button button-primary button-small" onClick={addReminder} data-testid="button-empty-reminders"><Plus size={15}/>Add a reminder</button></div>:<div className="reminder-list">{[...store.reminders].sort((a,b)=>a.dueAt.localeCompare(b.dueAt)).map(r=><article className={`reminder-row ${r.completed?'is-done':''}`} key={r.id} data-testid={`row-reminder-${r.id}`}><button className="check-button" onClick={()=>{p.setStore(s=>({...s,reminders:s.reminders.map(x=>x.id===r.id?{...x,completed:!x.completed}:x)}));p.notify(r.completed?'Reminder reopened':'Reminder complete');}} aria-label="Toggle reminder" data-testid={`button-toggle-reminder-${r.id}`}>{r.completed?<Check size={14}/>:<Circle size={16}/>}</button><span className="reminder-type-icon"><Bell size={16}/></span><div className="planner-task-text"><h3>{r.title}</h3><div className="task-meta"><span className={`task-type type-${r.type}`}>{r.type}</span><span>{subjectName(store,r.subjectId)}</span><span>{new Date(r.dueAt).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</span></div></div><div className="row-actions"><button className="icon-button tiny" onClick={()=>editReminder(r)} aria-label="Edit reminder" data-testid={`button-edit-reminder-${r.id}`}><Pencil size={14}/></button><button className="icon-button tiny danger-hover" onClick={()=>p.askDelete('reminders',r.id,r.title)} aria-label="Delete reminder" data-testid={`button-delete-reminder-${r.id}`}><Trash2 size={14}/></button></div></article>)}</div>}</section>}
    {plannerTab==='smart'&&<section className="planner-section smart-planner"><div className="smart-intro"><div className="smart-spark"><Sparkles size={22}/></div><span className="eyebrow">A PLAN, MADE FROM YOUR REAL TOPICS</span><h2>What fits in your day?</h2><p>We’ll prioritize unfinished topics by their priority and your nearest subject exams. Nothing is added to your schedule until you choose to do it.</p></div><div className="available-time"><label htmlFor="available-minutes">I have about</label><input id="available-minutes" type="number" min="1" max="600" value={available} onChange={e=>{setAvailable(Number(e.target.value));setPlan(null);}} data-testid="input-available-minutes"/><span>minutes to study</span><button className="button button-primary" onClick={smartPlan} data-testid="button-generate-plan"><Sparkles size={15}/>Make my plan</button></div>{plan&&<div className="generated-plan" data-testid="smart-plan-results"><div className="plan-result-head"><div><span className="eyebrow">YOUR TIME-BOUNDED PLAN</span><h3>{plan.length?`${Math.min(Number(available),plan.length*30)} minutes · ${plan.length} ${plan.length===1?'topic':'topics'}`:'A gentle blank slate'}</h3></div><span className="plan-chip"><Clock3 size={13}/>{Number(available)} min available</span></div>{plan.length?plan.map((t,i)=><div className="plan-topic" key={t.id}><span className="plan-step">{String(i+1).padStart(2,'0')}</span><div><strong>{t.name}</strong><small>{subjectName(store,t.subjectId)} · {store.lessons.find(l=>l.id===t.lessonId)?.name}</small></div><span className={`priority-tag priority-${t.priority}`}>{t.priority} priority</span><span className="plan-duration">{Math.min(30,Math.max(0,Number(available)-i*30))} min</span></div>):<div className="soft-empty plan-empty"><BookOpen size={22}/><strong>{store.topics.length?'All your topics are completed':'Add topics to make a study plan'}</strong><p>{store.topics.length?'You have earned a breather.':'Your plan can only include topics you have added to your syllabus.'}</p>{store.subjects.length===0&&<Link className="text-link" href="/study" data-testid="link-plan-add-topics">Go to your syllabus <ArrowRight size={14}/></Link>}</div>}</div>}</section>}
  </>;
}
function selectSubject(s:Store){return s.subjects.map(x=>({value:x.id,label:x.name}));}
function ProgressPage({store}:Shared){
  const total=store.topics.length,done=store.topics.filter(t=>t.status==='completed').length,inProgress=store.topics.filter(t=>t.status==='in_progress').length;
  const hours=store.sessions.reduce((n,s)=>n+s.durationSeconds,0)/3600;const attempts=store.quizzes.flatMap(q=>q.attempts);const quizPercent=attempts.length?Math.round(attempts.reduce((n,a)=>n+a.score/a.total*100,0)/attempts.length):0;
  const weekly=Array.from({length:7},(_,i)=>{const day=new Date();day.setDate(day.getDate()-6+i);const key=localDate(day);return {day:shortDays[dayIndex(day)],key,minutes:Math.round(store.sessions.filter(s=>localDate(new Date(s.startedAt))===key).reduce((n,s)=>n+s.durationSeconds,0)/60)};});
  const max=Math.max(30,...weekly.map(d=>d.minutes));
  return <><PageHeading eyebrow="LOOK HOW FAR YOU'VE COME" title="Your progress." description="A personal snapshot, built only from what you’ve done here."/>
    <div className="progress-hero"><div><span className="eyebrow">SYLLABUS COMPLETION</span><strong>{pct(done,total)}<small>%</small></strong><p>{done} completed {done===1?'topic':'topics'}{total?` out of ${total}`:' so far'}</p></div><div className="large-progress-ring" style={{'--progress':`${pct(done,total)*3.6}deg`} as CSSProperties}><div><BookOpen size={21}/><b>{done}<small> / {total}</small></b></div></div><div className="hero-progress-track"><i style={{width:`${pct(done,total)}%`}}/></div></div>
    <div className="progress-stat-grid"><div className="progress-stat"><span className="stat-icon stat-mint"><Clock3 size={18}/></span><span className="eyebrow">TOTAL STUDY TIME</span><strong>{hours<1?`${Math.round(hours*60)} min`:`${hours.toFixed(1)} hrs`}</strong><small>Across {store.sessions.length} {store.sessions.length===1?'session':'sessions'}</small></div><div className="progress-stat"><span className="stat-icon stat-peach"><CheckCircle2 size={18}/></span><span className="eyebrow">TOPICS COMPLETED</span><strong>{done}</strong><small>{inProgress} in progress · {total-done-inProgress} not started</small></div><div className="progress-stat"><span className="stat-icon stat-butter"><Target size={18}/></span><span className="eyebrow">QUIZ AVERAGE</span><strong>{attempts.length?`${quizPercent}%`:'—'}</strong><small>{attempts.length?`${attempts.length} quiz ${attempts.length===1?'attempt':'attempts'}`:'Your first quiz score will show here'}</small></div><div className="progress-stat"><span className="stat-icon stat-blue"><Flame size={18}/></span><span className="eyebrow">CURRENT STREAK</span><strong>{calcStreak(store.sessions)} <small>days</small></strong><small>One session at a time</small></div></div>
    <div className="progress-columns"><section className="panel activity-panel"><div className="section-title"><div><span className="eyebrow">LAST SEVEN DAYS</span><h2>Study activity</h2></div><span className="tiny-legend"><i/>minutes</span></div><div className="activity-chart">{weekly.map(d=><div className="activity-column" key={d.key} data-testid={`activity-day-${d.key}`}><strong>{d.minutes?`${d.minutes}m`:''}</strong><div className="bar-area"><i style={{height:`${Math.max(d.minutes?6:3,d.minutes/max*100)}%`}} className={d.minutes?'has-study':''}/></div><span>{d.day}</span></div>)}</div><div className="chart-caption"><TrendingUp size={15}/><span>Showing study sessions recorded in the last 7 days.</span></div></section><section className="panel breakdown-panel"><div className="section-title"><div><span className="eyebrow">YOUR SUBJECTS</span><h2>Learning progress</h2></div></div>{store.subjects.length?store.subjects.map(s=>{const topics=store.topics.filter(t=>t.subjectId===s.id),complete=topics.filter(t=>t.status==='completed').length;return <div className="subject-progress-row" key={s.id} data-testid={`progress-subject-${s.id}`}><div className="subject-progress-head"><span className="subject-dot">{s.name.slice(0,1).toUpperCase()}</span><strong>{s.name}</strong><span>{pct(complete,topics.length)}%</span></div><div className="progress-track"><i style={{width:`${pct(complete,topics.length)}%`}}/></div><small>{complete} of {topics.length} topics complete</small></div>}):<div className="breakdown-empty"><Layers3 size={20}/><strong>Your subjects will show up here</strong><p>Add a subject and start tracking your progress.</p><Link className="text-link" href="/study" data-testid="link-progress-add-subject">Go to Study <ArrowRight size={14}/></Link></div>}</section></div>
    <div className="progress-footnote"><Sparkles size={16}/><span>Your progress reflects only the subjects, sessions, and quizzes you add to StudyMate.</span></div>
  </>;
}
function FormModal({config,onClose,onSubmit}:{config:ModalConfig;onClose:()=>void;onSubmit:(v:Record<string,any>)=>void}){
  const [values,setValues]=useState<Record<string,any>>(()=>Object.fromEntries(config.fields.map(f=>[f.key,config.initial?.[f.key]??(f.kind==='select'?f.options?.[0]?.value??'':'')])));
  const [error,setError]=useState('');
  const submit=(e:FormEvent)=>{e.preventDefault();const missing=config.fields.find(f=>f.required&&!String(values[f.key]??'').trim());if(missing){setError(`${missing.label} is required.`);return;}onSubmit(values);};
  const change=(key:string,value:string)=>{setValues(v=>key==='subjectId'?({...v,[key]:value,lessonId:''}):({...v,[key]:value}));if(error)setError('');};
  return <div className="modal-scrim" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="form-modal" onSubmit={submit} data-testid="form-dialog"><div className="modal-heading"><div><span className="eyebrow">YOUR PERSONAL SPACE</span><h2>{config.title}</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close dialog" data-testid="button-close-dialog"><X size={18}/></button></div><div className="modal-fields">{config.fields.map(field=><label key={field.key} className={`form-field ${field.kind==='textarea'?'full-field':''}`}><span>{field.label}{field.required&&<i> *</i>}</span>{field.kind==='textarea'?<textarea value={values[field.key]??''} onChange={e=>change(field.key,e.target.value)} placeholder={field.placeholder||''} required={field.required} rows={4} data-testid={`input-${idTest(field.key)}`}/>:field.kind==='select'?<span className="modal-select"><select value={values[field.key]??''} onChange={e=>change(field.key,e.target.value)} required={field.required} data-testid={`select-${idTest(field.key)}`}>{(field.options||[]).filter(o=>field.key!=='lessonId'||!o.subjectId||o.subjectId===values.subjectId).map(o=><option value={o.value} key={o.value}>{o.label}</option>)}</select><ChevronDown size={14}/></span>:<input type={field.kind||'text'} value={values[field.key]??''} onChange={e=>change(field.key,e.target.value)} placeholder={field.placeholder||''} required={field.required} min={field.kind==='number'?1:undefined} data-testid={`input-${idTest(field.key)}`}/>}</label>)}</div>{error&&<div className="form-error" role="alert" data-testid="status-form-error">{error}</div>}<div className="modal-footer"><button type="button" className="button button-secondary" onClick={onClose} data-testid="button-cancel-form">Cancel</button><button type="submit" className="button button-primary" data-testid="button-save-form">{config.submitLabel||'Save changes'}<ArrowRight size={15}/></button></div></form></div>;
}

export default App;